import{_ as n,o,c as i,a0 as s,j as a,a as t,t as r}from"./chunks/framework.Cg_noeTw.js";const f=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),c={name:"explanation/architecture.md"};function l(d,e,p,h,m,g){return o(),i("div",null,[e[6]||(e[6]=s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Scarab is ports-and-adapters in two planes: <strong>config loading</strong> and <strong>templated content</strong>. Both are generic — scarab never names a consumer&#39;s types.</p><h2 id="the-config-plane" tabindex="-1">The config plane <a class="header-anchor" href="#the-config-plane" aria-label="Permalink to &quot;The config plane&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ConfigSource&lt;T&gt;  ──load()──▶  T            (the port)</span></span>
<span class="line"><span>      ▲                            ▲</span></span>
<span class="line"><span>      │ impl                       │ consumer&#39;s serde model</span></span>
<span class="line"><span>scarab-config-file          MyConfig, TamiasConfig, …</span></span>
<span class="line"><span>      │ dispatches by extension</span></span>
<span class="line"><span>ConfigFormat&lt;T&gt;  ──parse/render──▶  text   (syntax port)</span></span>
<span class="line"><span>      ▲</span></span>
<span class="line"><span>scarab-config-toml / scarab-config-yaml</span></span></code></pre></div><ul><li><code>scarab-config</code> is pure: traits, the <code>Discovery</code> spec, path helpers, and the JSON merge half (<code>merge_value</code> / <code>apply_overrides</code>) — no I/O, no formats, no models.</li><li><code>scarab-config-file</code> is the discovery impl every org repo copy-pasted: <code>FileSource</code> picks the <em>first</em> matching file; <code>LayeredFileSource</code> merges <em>every</em> dir&#39;s file plus explicit/override layers into one <code>T</code>. Both dispatch by extension across a format list.</li><li><code>scarab-config-toml</code> / <code>-yaml</code> own only syntax — serde parse/render over any <code>T</code>. Formats are separate crates so a consumer can carry just the syntax it wants. Layered loading parses each layer as <code>serde_json::Value</code> through the same blanket impls, so <code>T</code> itself never needs <code>Serialize</code>.</li></ul><p>Generic-over-<code>T</code> is the load-bearing decision: one <code>FileSource</code> serves <code>myco</code>, <code>tamias</code>, <code>tarsi</code>, and every future repo because the model stays in the consumer. The trait objects (<code>&amp;dyn ConfigFormat&lt;T&gt;</code>) keep <code>formats</code> heterogeneous without generics exploding at the call site.</p><p>Discovery is a <em>spec</em>, not a search loop — <code>FileSource</code> interprets it, and env/remote <code>ConfigSource</code> impls can reuse the same vocabulary (<code>env_var</code>, <code>dirs</code>, preference order) without inheriting file semantics.</p><h2 id="the-template-plane" tabindex="-1">The template plane <a class="header-anchor" href="#the-template-plane" aria-label="Permalink to &quot;The template plane&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tamias pack (type: template)</span></span>
<span class="line"><span>      │  tamias.yaml \`template:\` table</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>scarab-template ── PackTemplate/TemplateFile/TemplateEngine (pure)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>tamias-driver-template ── verbs, vars, state file (the ops impl)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>scarab-template-minijinja ── the one engine impl (v1)</span></span></code></pre></div>`,9)),a("ul",null,[e[5]||(e[5]=s("<li><code>scarab-template</code> holds the pack model and path safety — pure domain, engine-agnostic. <code>merge_context</code> defines layer precedence; <code>safe_into</code>/<code>safe_src</code> define what &quot;inside the target&quot; means. <code>template.extends</code> composes packs: tamias materializes each ancestor&#39;s payload at <code>.scarab-parent/</code>, and the driver renders the chain ancestor-first so children override parents on <code>into</code> conflicts — inheritance without a fetch capability in the driver.</li><li><code>tamias-driver-template</code> is where I/O lives: manifest loading, chain walking, var resolution (ancestor defaults → pack defaults → auto → file → env → args), render+write, digest state. It implements the tamias driver contract, so packs distribute through tamias like every other content type — no bespoke install path.</li>",2)),a("li",null,[e[0]||(e[0]=a("code",null,"scarab-template-minijinja",-1)),e[1]||(e[1]=t(" is deliberately the only engine: minijinja is small, sandboxed by construction, and its ",-1)),a("code",null,r(),1),e[2]||(e[2]=t("/",-1)),e[3]||(e[3]=a("code",null,"{% %}",-1)),e[4]||(e[4]=t(" syntax covers config-file templating without a plugin system. The port exists so a second syntax family can land without touching the model or the driver.",-1))])]),e[7]||(e[7]=s('<h2 id="why-the-split" tabindex="-1">Why the split <a class="header-anchor" href="#why-the-split" aria-label="Permalink to &quot;Why the split&quot;">​</a></h2><p>Config and templates share a shape — <em>declared inputs in, files out</em> — but not a mechanism. Config is <em>read</em>: find a file, parse to a typed model. Templates are <em>write</em>: render declared sources to declared targets with a variable context. Keeping them as separate ports means a consumer can adopt one without the other, and each plane&#39;s invariants (discovery order vs. path safety + digest state) stay local.</p><h2 id="invariants-worth-knowing" tabindex="-1">Invariants worth knowing <a class="header-anchor" href="#invariants-worth-knowing" aria-label="Permalink to &quot;Invariants worth knowing&quot;">​</a></h2><ul><li><strong>Formats prefer YAML.</strong> Within a directory, <code>yaml</code> → <code>yml</code> → <code>toml</code>; across dirs, earlier dirs win regardless of format.</li><li><strong>Named paths fail loudly.</strong> An explicit/<code>$*_CONFIG</code> path that misses is an error; discovery candidates skip silently.</li><li><strong>Templates can&#39;t escape.</strong> <code>..</code>/absolute/empty targets are rejected at validation, before any write.</li><li><strong>Uninstall is digest-exact.</strong> Only files still matching their recorded sha256 are removed; user edits are preserved and reported.</li><li><strong>Layers merge as JSON, not as <code>T</code>.</strong> <code>LayeredFileSource</code> folds <code>serde_json::Value</code> trees — objects key-wise, scalars/arrays replace — before one final deserialize, so merge semantics stay format- and model-agnostic.</li><li><strong>Secrets stay names.</strong> Config surfaces carry secret <em>names</em>, never values — cuora owns the values.</li></ul><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>Scarab is a <strong>library</strong> in the org&#39;s layering — below the engines, consumed through tamias. The stack is <strong>tamias</strong> (package &amp; content manager) → <strong>engines</strong> (myco, kuda, mimus, sepia, sturn, hypha, tarsi, cicada, cypera, peregrin) → <strong>orchestration</strong> (peregrin campaigns) → <strong>surfaces</strong> (pavo, MCP fronts).</p><p>Scarab doesn&#39;t run anywhere itself: engines call <code>scarab-config</code> to load their <code>&lt;name&gt;.yaml</code>/<code>.toml</code>, and tamias distributes <code>type: template</code> packs that <code>tamias-driver-template</code> renders. It sits beside the engines as shared expertise — the config port every engine agrees on, the template mechanism every pack shares.</p>',7))])}const y=n(c,[["render",l]]);export{f as __pageData,y as default};
